WorkflowProcessEvent.eventDescription:
function servicetask16(attempt, message) {

    var COLIGADA = "1";
    var COLIGADAS_BANCO = ["1", "2", "5", "6", "12", "13"];

    function f(nome) {
        return String(hAPI.getCardValue(nome) || "").trim();
    }

    var categoria     = f("categoria");   
    var classificacao = f("classificacao");   
    var tipo          = f("tipo");            

    var razaoSocial   = f("razaoSocial");
    var nomeFantasia  = f("nomeFantasia");
    var nomeRM        = razaoSocial;

    var cnpj          = f("docCnpj").replace(/[^A-Za-z0-9]/g, "").toUpperCase();
    var cpf           = f("docCpf").replace(/\D/g, "");
    var cgc           = (categoria === "J") ? cnpj : cpf;

    var rg            = f("docRg");
    var rgOrgao       = f("docRgOrgao");
    var rgUf          = f("docRgUf");
    var dtNascimento  = f("dtNascimento");
    var estadoCivil   = f("estadoCivil");
    var numDependentes= f("numDependentes") || "0";

    var inscEstadual  = f("docInscricaoEstadual");
    var inscMunicipal = f("docInscricaoMunicipal");

    var endereco      = f("endereco");
    var numero        = f("numero");
    var complemento   = f("complemento").substring(0, 40);
    var bairro        = f("bairro");
    var cidade        = f("cidade");
    var estado        = f("estado");
    var cep           = f("cep");
    var codMunicipio  = f("codMunicipio");

    var telefone      = f("telefone");
    var celular       = f("celular");
    var emailCr       = f("emailCr") || f("emailAdministrativo") || f("emailComercial");


    var estrangeiro       = f("hiddenToggleEstrangeiro") === "on";
    var docEstrangeiro    = f("docEstrangeiro");
    var nacionalidade     = estrangeiro ? "1" : "0";

    var contribuinte  = f("icms")           || "0";
    var simplesNac    = f("simplesNacional") || "0";
    var retencaoIss   = "0";
    var codReceita    = f("hiddenCodIrrf") || f("codIrrf") || "";
    var natRendimento = f("idNatRendimento") || "";

    var mapPagrec = { "1": "2", "2": "1", "3": "3" };
    var pagrec = mapPagrec[classificacao] || "1";

    var dtNascimentoRM = "";
    if (dtNascimento) {
        if (/^\d{4}-\d{2}-\d{2}$/.test(dtNascimento)) {
            dtNascimentoRM = dtNascimento + "T00:00:00";
        } else {
            var partesDt = dtNascimento.split("/");
            if (partesDt.length === 3) {
                dtNascimentoRM = partesDt[2] + "-" + partesDt[1] + "-" + partesDt[0] + "T00:00:00";
            }
        }
    }


    if (categoria === "F" && !rg) {
        throw new Error("[ST16] Pessoa Física: campo 'RG (Cédula de Identidade)' está vazio no formulário. Preencha o campo RG e reenvie.");
    }
    if (categoria === "F" && !dtNascimentoRM) {
        throw new Error("[ST16] Pessoa Física: campo 'Data de Nascimento' está vazio ou em formato inválido (esperado DD/MM/AAAA). Preencha e reenvie.");
    }
    if (categoria === "F" && !estadoCivil) {
        throw new Error("[ST16] Pessoa Física: campo 'Estado Civil' está vazio. Preencha e reenvie.");
    }


    function chamarRM(dataServerName, xml, coligadaOverride) {
        var col = coligadaOverride || COLIGADA;
        log.info("[ST16] Chamando ds_saveRecordRM ? " + dataServerName + " | coligada=" + col);

        var c = [
            DatasetFactory.createConstraint("pDataServerName", dataServerName, dataServerName, ConstraintType.MUST),
            DatasetFactory.createConstraint("pXML",            xml,            xml,            ConstraintType.MUST),
            DatasetFactory.createConstraint("pCodcoligada",    col,            col,            ConstraintType.MUST)
        ];

        var ds = DatasetFactory.getDataset("ds_saveRecordRM", null, c, null);

        if (!ds || !ds.values || !ds.values.length) {
            throw new Error("[ST16] ds_saveRecordRM não retornou dados. DataServer=" + dataServerName);
        }

        var row    = ds.values[0];

        var status = String(row[0] || "").trim();
        var msg    = String(row[1] || "").trim();
        var result = String(row[2] || "").trim();

        log.info("[ST16] ds_saveRecordRM STATUS=" + status + " | MENSAGEM=" + msg);

        if (status !== "SUCCESS") {
            throw new Error("[ST16][RM] " + msg);
        }


        if (result && result !== "null") {
            var obj = JSON.parse(result);
            return String(obj.codigo || "").trim();
        }

        return "";
    }
    var xmlCfoPF = "";
    if (categoria === "F") {
        xmlCfoPF =
            "<CIDENTIDADE>"   + x(rg)             + "</CIDENTIDADE>" +
            "<DTNASCIMENTO>"  + x(dtNascimentoRM) + "</DTNASCIMENTO>" +
            "<ESTADOCIVIL>"   + x(estadoCivil)    + "</ESTADOCIVIL>" +
            "<CI_ORGAO>"      + x(rgOrgao)        + "</CI_ORGAO>" +
            "<CI_UF>"         + x(rgUf)           + "</CI_UF>" +
            "<NUMDEPENDENTES>"+ x(numDependentes) + "</NUMDEPENDENTES>";
    }

    var xmlCfo =
        "<FinCFOBR>" +
            "<FCFO>" +
                "<CODCOLIGADA>0</CODCOLIGADA>" +
                "<CODCFO>-1</CODCFO>" +
                "<NOME>"           + x(nomeRM)       + "</NOME>" +
                "<NOMEFANTASIA>"   + x(nomeFantasia)  + "</NOMEFANTASIA>" +
                "<CGCCFO>"         + x(cgc)           + "</CGCCFO>" +
                "<INSCRESTADUAL>"  + x(inscEstadual)  + "</INSCRESTADUAL>" +
                "<INSCRMUNICIPAL>" + x(inscMunicipal) + "</INSCRMUNICIPAL>" +
                "<PAGREC>"         + pagrec            + "</PAGREC>" +
                "<RUA>"            + x(endereco)      + "</RUA>" +
                "<NUMERO>"         + x(numero)        + "</NUMERO>" +
                "<COMPLEMENTO>"    + x(complemento)   + "</COMPLEMENTO>" +
                "<BAIRRO>"         + x(bairro)        + "</BAIRRO>" +
                "<CIDADE>"         + x(cidade)        + "</CIDADE>" +
                "<CODETD>"         + x(estado)        + "</CODETD>" +
                "<CEP>"            + x(cep)           + "</CEP>" +
                "<CODMUNICIPIO>"   + x(codMunicipio)  + "</CODMUNICIPIO>" +
                "<TELEFONE>"       + x(telefone)      + "</TELEFONE>" +
                "<TELEX>"          + x(celular)       + "</TELEX>" +
                "<EMAIL>"          + x(emailCr)       + "</EMAIL>" +
                "<CODTCF>"         + x(tipo)          + "</CODTCF>" +
                "<ATIVO>1</ATIVO>" +
                "<CODCOLTCF>0</CODCOLTCF>" +
                "<PESSOAFISOUJUR>" + x(categoria)     + "</PESSOAFISOUJUR>" +
                "<PAIS>Brasil</PAIS>" +
                "<CONTRIBUINTE>"       + contribuinte  + "</CONTRIBUINTE>" +
                "<CONTRIBUINTEISS>"    + retencaoIss   + "</CONTRIBUINTEISS>" +
                "<IDCFO>0</IDCFO>" +
                "<OPTANTEPELOSIMPLES>" + simplesNac    + "</OPTANTEPELOSIMPLES>" +
                "<TIPORUA>1</TIPORUA>" +
                "<TIPOBAIRRO>1</TIPOBAIRRO>" +
                "<REGIMEISS>N</REGIMEISS>" +
                "<RETENCAOISS>"        + retencaoIss   + "</RETENCAOISS>" +
                "<IDPAIS>1</IDPAIS>" +
                "<NACIONALIDADE>"      + nacionalidade + "</NACIONALIDADE>" +
                (estrangeiro ? "<DOCUMENTOESTRANGEIRO>" + x(docEstrangeiro) + "</DOCUMENTOESTRANGEIRO>" : "") +
                (codReceita    ? "<CODRECEITA>"      + x(codReceita)    + "</CODRECEITA>"      : "") +
                (natRendimento ? "<IDNATRENDIMENTO>" + x(natRendimento) + "</IDNATRENDIMENTO>" : "") +
                "<TIPORENDIMENTO>000</TIPORENDIMENTO>" +
                xmlCfoPF +
            "</FCFO>" +
        "</FinCFOBR>";

    var codCfo = chamarRM("FinCFODataBR", xmlCfo);

    if (!codCfo) {
        throw new Error("[ST16] CODCFO não retornado pelo RM após criação do CFO.");
    }

    log.info("[ST16] CFO criado com sucesso. CODCFO=" + codCfo);
    hAPI.setCardValue("codCfoRm", codCfo);


    for (var i = 1; i <= 5; i++) {
        var bancoCod  = f("hiddenBanco" + i + "Cod");
        var bancoDesc = f("hiddenBanco" + i + "Desc");
        var agencia   = f("hiddenBanco" + i + "Agencia");
        var conta     = f("hiddenBanco" + i + "Conta");

        log.info("[ST16] Banco " + i + " — cod=" + bancoCod + " | agencia=" + agencia + " | conta=" + conta + " | desc=" + bancoDesc);

        if (!bancoCod && !agencia && !conta) {
            log.info("[ST16] Banco " + i + " sem dados — ignorando.");
            continue;
        }

        var agNum = agencia.length > 1 ? agencia.slice(0, -1) : agencia;
        var agDig = agencia.length > 1 ? agencia.slice(-1)    : "0";
        var ctNum = conta.length   > 1 ? conta.slice(0, -1)   : conta;
        var ctDig = conta.length   > 1 ? conta.slice(-1)      : "0";

        var ativo = (i === 1) ? "1" : "0";

        for (var ci = 0; ci < COLIGADAS_BANCO.length; ci++) {
            var colAtual = COLIGADAS_BANCO[ci];

            var xmlBanco =
                "<FDadosPgto>" +
                    "<CODCOLIGADA>"  + colAtual                                                          + "</CODCOLIGADA>" +
                    "<CODCOLCFO>0</CODCOLCFO>" +
                    "<CODCFO>"       + x(codCfo)                                                         + "</CODCFO>" +
                    "<IDPGTO>" + i + "</IDPGTO>" +
                    "<DESCRICAO>"    + x("Conta " + i + (bancoDesc ? " - " + bancoDesc : ""))            + "</DESCRICAO>" +
                    "<FORMAPAGAMENTO>I</FORMAPAGAMENTO>" +
                    "<FAVORECIDO>"   + x(nomeRM)                                                         + "</FAVORECIDO>" +
                    "<CGCFAVORECIDO>"+ x(cgc)                                                            + "</CGCFAVORECIDO>" +
                    "<ATIVO>" + ativo + "</ATIVO>" +
                    "<NUMEROBANCO>"  + x(bancoCod)                                                       + "</NUMEROBANCO>" +
                    "<CODIGOAGENCIA>"+ x(agNum)                                                          + "</CODIGOAGENCIA>" +
                    "<DIGITOAGENCIA>"+ x(agDig)                                                          + "</DIGITOAGENCIA>" +
                    "<NOMEAGENCIA>"  + x(bancoDesc)                                                      + "</NOMEAGENCIA>" +
                    "<CONTACORRENTE>"+ x(ctNum)                                                          + "</CONTACORRENTE>" +
                    "<DIGITOCONTA>"  + x(ctDig)                                                          + "</DIGITOCONTA>" +
                    "<TIPOCONTA>1</TIPOCONTA>" +
                "</FDadosPgto>";

            try {
                chamarRM("FinDadosPgtoDataBR", xmlBanco, colAtual);
                log.info("[ST16] Conta " + i + " / Coligada " + colAtual + " salva com sucesso.");
            } catch (eBanco) {
                log.warn("[ST16] Falha conta " + i + " / Coligada " + colAtual + ": " + eBanco);
            }
        }
    }

}



function x(s) {
    return (s || "").toString()
        .replace(/&/g,  "&amp;")
        .replace(/</g,  "&lt;")
        .replace(/>/g,  "&gt;")
        .replace(/"/g,  "&quot;");
}

function afterProcessFinish(colleagueId, processId, threadSequence, userList) {
    try {
        var solicitante = hAPI.getCardValue("solicitante");
        if (!solicitante) {
            solicitante = colleagueId;
        }

        var email = buscaEmailUsuarioFluig(solicitante);
        if (!email) {
            log.warn("[E-MAIL] Solicitante sem e-mail cadastrado: " + solicitante);
            return;
        }

        var link = URL_FLUIG + "/portal/p/1/pageworkflowview?app_ecm_workflowview_detailsProcessInstanceID=" + processId;

        var corpoEmail = "";
        corpoEmail += "Olá, <br>";
        corpoEmail += "Sua solicitação nº " + processId + " de <b>Cadastro de Cliente/Fornecedor</b> foi <b>finalizada</b>.<br>";
        corpoEmail += "<br>";
        corpoEmail += "Para consultar os detalhes, <a href='" + link + "'>clique aqui</a>.";

        enviarEmailFluig(email, "Cadastro de Cliente/Fornecedor finalizado - #" + processId, corpoEmail);
    } catch (e) {
        log.error("[E-MAIL] Erro ao notificar finalização: " + e);
    }
}



// NOTIFICAÇÃO POR E-MAIL 
var URL_FLUIG = "http://fluig.castilho.com.br:1010";             // Produção
// var URL_FLUIG = "http://homologacao.castilho.com.br:2020";   // Homologação


function buscaEmailUsuarioFluig(login) {
    var c1 = DatasetFactory.createConstraint("login", login, login, ConstraintType.MUST);
    var dataset = DatasetFactory.getDataset("colleague", null, [c1], null);

    if (dataset != null && dataset.rowsCount > 0) {
        return dataset.getValue(0, "mail");
    }

    return null;
}


function enviarEmailFluig(email, assunto, corpoEmail) {
    var data = {
        "to": email,
        from: "fluig@construtoracastilho.com.br",
        "subject": assunto,
        "templateId": "TPL_PADRAO_CASTILHO",
        "dialectId": "pt_BR",
        "param": {
            "CORPO_EMAIL": corpoEmail,
            "SERVER_URL": URL_FLUIG,
            "TENANT_ID": "1"
        }
    };

    var clientService = fluigAPI.getAuthorizeClientService();
    var requestData = {
        companyId: getValue("WKCompany") + '',
        serviceCode: 'ServicoFluig',
        endpoint: '/api/public/alert/customEmailSender',
        method: 'post',
        params: data,
        options: {
            encoding: 'UTF-8',
            mediaType: 'application/json',
            useSSL: true
        },
        headers: {
            "Content-Type": 'application/json;charset=UTF-8'
        }
    };

    var vo = clientService.invoke(JSONUtil.toJSON(requestData));

    if (vo.getResult() == null || vo.getResult().isEmpty()) {
        throw new Exception("Retorno do envio de e-mail está vazio");
    } else {
        log.info("[E-MAIL] Enviado para " + email + " | assunto: " + assunto);
        return vo.getResult();
    }
}

function beforeTaskSave(colleagueId, nextSequenceId, userList) {
    var atividadeAtual = Number(getValue("WKNumState"));
    var completTask = getValue("WKCompletTask") == "true";

    log.info("[E-MAIL-DEBUG] beforeTaskSave | atividade=" + atividadeAtual + " | colleagueId=" + colleagueId + " | completTask=" + completTask + " | WKUser=" + getValue("WKUser"));

    if (!completTask) {
        return;
    }

    if (atividadeAtual == 0 || atividadeAtual == 4) {
        if (!hAPI.getCardValue("solicitante")) {
            hAPI.setCardValue("solicitante", colleagueId);
        }
        adicionarHistorico(colleagueId, "Solicitação", "Enviado", "Solicitação enviada para validação.");
        return;
    }

    if (atividadeAtual == 11) {
        var decisao = hAPI.getCardValue("selectDecisao");
        var observacao = hAPI.getCardValue("observacaoValidacao");

        var acao = "";
        var atividade = "Validação";

        if (decisao == "Correcao") {
            acao = "Correção do Cadastro";
        } else if (decisao == "enviarRm") {
            acao = "Enviar ao RM";
        } else {
            acao = "Validação";
        }


        var motivoCorrecao = observacao;

        if (!observacao) {
            observacao = "Decisão registrada na etapa de validação.";
        }

        var alteracoes = montarAlteracoesEdicaoValidacao();

        if (alteracoes) {
            observacao += alteracoes;
        }

        adicionarHistorico(colleagueId, atividade, acao, observacao);

        if (decisao == "Correcao") {
            notificarSolicitanteCorrecao(motivoCorrecao, userList, colleagueId);
        }


        hAPI.setCardValue("observacaoValidacao", "");
        hAPI.setCardValue("selectDecisao", "");
        hAPI.setCardValue("snapshotEdicaoValidacao", "");

        return;
    }

    if (atividadeAtual == 27) {
        var observacao = hAPI.getCardValue("observacaoValidacao");

        if (!observacao) {
            observacao = "Cadastro ajustado e reenviado para validação.";
        }

        adicionarHistorico(
            colleagueId,
            "Correção Cadastro",
            "Reenvio para Validação",
            observacao
        );

        hAPI.setCardValue("observacaoValidacao", "");
        hAPI.setCardValue("selectDecisao", "");

        return;
    }
}



// HISTÓRICO DE DECISÃO
function adicionarHistorico(usuario, atividade, acao, observacao) {
    hAPI.addCardChild("tableHistorico", {
        tableHistoricoUsuario: usuario,
        tableHistoricoData: new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss").format(new java.util.Date()),
        tableHistoricoAtividade: atividade,
        tableHistoricoObservacao: observacao,
        tableHistoricoAcao: acao
    });
}


// AUDITORIA DE EDIÇÃO NA VALIDAÇÃO
function montarAlteracoesEdicaoValidacao() {
    var snapshotTexto = hAPI.getCardValue("snapshotEdicaoValidacao");

    if (!snapshotTexto) {
        return "";
    }

    var snapshot = {};

    try {
        snapshot = JSON.parse(snapshotTexto);
    } catch (e) {
        log.error("Erro ao ler snapshotEdicaoValidacao: " + e);
        return "";
    }


    var campos = [
        ["classificacao", "Classificação"],
        ["categoria", "Categoria"],
        ["tipo", "Tipo"],
        ["classificacaoOperacional", "Classificação Operacional"],

        ["docCpf", "CPF"],
        ["docCnpj", "CNPJ"],
        ["docRg", "RG"],
        ["docInscricaoEstadual", "Inscrição Estadual"],

        ["razaoSocial", "Razão Social"],
        ["nomeFantasia", "Nome Fantasia"],
        ["cep", "CEP"],
        ["endereco", "Endereço"],
        ["numero", "Número"],
        ["complemento", "Complemento"],
        ["bairro", "Bairro"],
        ["cidade", "Cidade"],
        ["pais", "País"],
        ["estado", "Estado"],

        ["icms", "Contribuinte ICMS"],
        ["codIrrf", "Código de Receita IRRF"],
        ["irrf", "Alíquota IRRF"],
        ["simplesNacional", "Simples Nacional"],
        ["codNaturezaRendimento", "Natureza de Rendimentos"],
        ["regimeFiscal", "Regime Fiscal"],
        ["tipoDocEmitido", "Tipo de Documento Emitido"],

        ["grupoMercadoria1", "Grupo de Mercadoria 1"],
        ["hiddenGrupoMercadoria2", "Grupo de Mercadoria 2"],
        ["hiddenGrupoMercadoria3", "Grupo de Mercadoria 3"],
        ["hiddenGrupoMercadoria4", "Grupo de Mercadoria 4"],
        ["hiddenGrupoMercadoria5", "Grupo de Mercadoria 5"],
        ["hiddenGrupoMercadoria6", "Grupo de Mercadoria 6"],
        ["hiddenGrupoMercadoria7", "Grupo de Mercadoria 7"],
        ["hiddenGrupoMercadoria8", "Grupo de Mercadoria 8"],
        ["hiddenGrupoMercadoria9", "Grupo de Mercadoria 9"],

        ["cnaePrincipal", "CNAE Principal"],
        ["hiddenCnaeSecundario1", "CNAE Secundário 1"],
        ["hiddenCnaeSecundario2", "CNAE Secundário 2"],
        ["hiddenCnaeSecundario3", "CNAE Secundário 3"],
        ["hiddenCnaeSecundario4", "CNAE Secundário 4"],
        ["hiddenCnaeSecundario5", "CNAE Secundário 5"],
        ["toggleRetencao", "Haverá retenção?"],
        ["iss", "Retenção ISS"],
        ["inss", "Retenção INSS"],
        ["inputIrrf", "Retenção IRRF"],
        ["csll", "Retenção CSLL"],
        ["pis", "Retenção PIS"],
        ["cofins", "Retenção COFINS"],

        ["hiddenBanco1Condicao", "Condição de Pagamento (Conta 1)"],
        ["hiddenBanco1Cod",     "Banco (Conta 1)"],
        ["hiddenBanco1Agencia", "Agência (Conta 1)"],
        ["hiddenBanco1Conta",   "Conta (Conta 1)"],
        ["hiddenBanco2Condicao", "Condição de Pagamento (Conta 2)"],
        ["hiddenBanco2Cod",      "Banco (Conta 2)"],
        ["hiddenBanco2Agencia",  "Agência (Conta 2)"],
        ["hiddenBanco2Conta",    "Conta (Conta 2)"],
        ["hiddenBanco3Condicao", "Condição de Pagamento (Conta 3)"],
        ["hiddenBanco3Cod",      "Banco (Conta 3)"],
        ["hiddenBanco3Agencia",  "Agência (Conta 3)"],
        ["hiddenBanco3Conta",    "Conta (Conta 3)"],
        ["hiddenBanco4Condicao", "Condição de Pagamento (Conta 4)"],
        ["hiddenBanco4Cod",      "Banco (Conta 4)"],
        ["hiddenBanco4Agencia",  "Agência (Conta 4)"],
        ["hiddenBanco4Conta",    "Conta (Conta 4)"],
        ["hiddenBanco5Condicao", "Condição de Pagamento (Conta 5)"],
        ["hiddenBanco5Cod",      "Banco (Conta 5)"],
        ["hiddenBanco5Agencia",  "Agência (Conta 5)"],
        ["hiddenBanco5Conta",    "Conta (Conta 5)"],

        ["telefone", "Telefone"],
        ["telComercial", "Telefone Comercial"],
        ["celular", "Celular"],
        ["emailAdministrativo", "E-mail Administrativo"],
        ["emailComercial", "E-mail Comercial"],
        ["emailCr", "E-mail Financeiro / Contabilidade"],
        ["site", "Site"],

        ["anxCartaoCnpj", "Anexo Documento de Identificação Júridica"],
        ["anxCompBanco", "Anexo Comprovante Bancário"],
        ["anxContrato", "Anexo Contrato Social"],
        ["anxRgCpf", "Anexo RG / CPF"],
        ["anxCompEndereco", "Anexo Comprovante de Endereço"],
        ["anxLaudoPcd", "Anexo Laudo Médico PCD"],
        ["anxDependentes", "Anexo Dependentes IRRF"],
        ["anxCodConduta", "Anexo Código de Conduta"],
        ["anxAntiCorrupcao", "Anexo Política Anticorrupção"],
        ["anxConflito", "Anexo Conflito de Interesses"],
        ["anxLgpd", "Anexo Ciência LGPD"]
    ];

    var alteracoes = [];

    for (var i = 0; i < campos.length; i++) {
        var campo = campos[i][0];
        var label = campos[i][1];

        var antigo = String(snapshot[campo] || "").trim();
        var novo = String(hAPI.getCardValue(campo) || "").trim();

        if (isCampoCheckboxAuditoria(campo)) {
            antigo = normalizarCheckboxAuditoria(antigo);
            novo = normalizarCheckboxAuditoria(novo);
        }

        if (antigo != novo) {
            alteracoes.push(label + ": de '" + antigo + "' para '" + novo + "'");
        }
    }

    if (alteracoes.length == 0) {
        return "";
    }

    return "<br><br><b>Alterações realizadas:</b><br>• " + alteracoes.join("<br>• ");
}

function isCampoCheckboxAuditoria(campo) {
    return [
        "toggleEstrangeiro",
        "toggleRetencao",
        "iss",
        "inss",
        "inputIrrf",
        "csll",
        "pis",
        "cofins"
    ].indexOf(campo) >= 0;
}


function normalizarCheckboxAuditoria(valor) {
    var v = String(valor || "").toLowerCase().trim();

    if (v == "on" || v == "true" || v == "1" || v == "sim" || v == "s") {
        return "Sim";
    }

    return "Não";
}



// var URL_FLUIG = "http://fluig.castilho.com.br:1010";             // Produção
var URL_FLUIG = "http://homologacao.castilho.com.br:2020";   // Homologação

function notificarSolicitanteCorrecao(motivo, userList, colleagueId) {
    try {
        // 1) Fonte primária: card "solicitante" (salvo na abertura, p/ processos novos).
        var solicitante = hAPI.getCardValue("solicitante");
        log.info("[E-MAIL] solicitante (card) = '" + solicitante + "'");

        // 2) Fallback: destinatário da próxima atividade (a correção volta ao solicitante).
        if (!solicitante && userList != null) {
            try {
                if (userList.size() > 0) {
                    solicitante = String(userList.get(0));
                    log.info("[E-MAIL] fallback userList[0] = '" + solicitante + "'");
                }
            } catch (eu) {
                log.warn("[E-MAIL] erro ao ler userList: " + eu);
            }
        }

        // 3) Último recurso: quem está movendo a tarefa.
        if (!solicitante) {
            solicitante = colleagueId;
            log.info("[E-MAIL] fallback colleagueId = '" + solicitante + "'");
        }

        var email = buscaEmailUsuarioFluig(solicitante);
        log.info("[E-MAIL] e-mail encontrado para '" + solicitante + "' = '" + email + "'");

        if (!email) {
            log.warn("[E-MAIL] Solicitante sem e-mail cadastrado: " + solicitante);
            return;
        }

        if (!motivo) {
            motivo = "Sem observação informada.";
        }

        var numProcesso = getValue("WKNumProces");
        var link = URL_FLUIG + "/portal/p/1/pageworkflowview?app_ecm_workflowview_detailsProcessInstanceID=" + numProcesso;

        var corpoEmail = "";
        corpoEmail += "Olá, <br>";
        corpoEmail += "Sua solicitação nº " + numProcesso + " de <b>Cadastro de Cliente/Fornecedor</b> foi enviada para <b>CORREÇÃO DE CADASTRO</b> pela equipe de validação.<br>";
        corpoEmail += "<br>";
        corpoEmail += "<b>Motivo / Observação:</b><br>" + motivo + "<br>";
        corpoEmail += "<br>";
        corpoEmail += "Para realizar os ajustes, <a href='" + link + "'>clique aqui</a>.";

        enviarEmailFluig(email, "Cadastro de Cliente/Fornecedor enviado para CORREÇÃO - #" + numProcesso, corpoEmail);
    } catch (e) {
        log.error("[E-MAIL] Erro ao notificar correção: " + e);
        if (e.javaException) {
            log.error("[E-MAIL] Causa (Java): " + e.javaException);
        }
    }
}


function buscaEmailUsuarioFluig(login) {
    var c1 = DatasetFactory.createConstraint("login", login, login, ConstraintType.MUST);
    var dataset = DatasetFactory.getDataset("colleague", null, [c1], null);

    if (dataset != null && dataset.rowsCount > 0) {
        return dataset.getValue(0, "mail");
    }

    return null;
}


function enviarEmailFluig(email, assunto, corpoEmail) {
    var data = {
        "to": email,
        from: "fluig@construtoracastilho.com.br",
        "subject": assunto,
        "templateId": "TPL_PADRAO_CASTILHO",
        "dialectId": "pt_BR",
        "param": {
            "CORPO_EMAIL": corpoEmail,
            "SERVER_URL": URL_FLUIG,
            "TENANT_ID": "1"
        }
    };

    var clientService = fluigAPI.getAuthorizeClientService();
    var requestData = {
        companyId: getValue("WKCompany") + '',
        serviceCode: 'ServicoFluig',
        endpoint: '/api/public/alert/customEmailSender',
        method: 'post',
        params: data,
        options: {
            encoding: 'UTF-8',
            mediaType: 'application/json',
            useSSL: true
        },
        headers: {
            "Content-Type": 'application/json;charset=UTF-8'
        }
    };

    log.info("[E-MAIL] Chamando customEmailSender | to=" + email + " | company=" + getValue("WKCompany"));

    var vo = clientService.invoke(JSONUtil.toJSON(requestData));
    log.info("[E-MAIL] Retorno customEmailSender: " + (vo == null ? "null" : vo.getResult()));

    if (vo == null || vo.getResult() == null || vo.getResult().isEmpty()) {
        throw new Exception("Retorno do envio de e-mail está vazio");
    } else {
        log.info("[E-MAIL] Enviado para " + email + " | assunto: " + assunto);
        return vo.getResult();
    }
}
